def reward_completeness_and_termination(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        score = 0.0

        # Check for <thinking> tag
        has_thinking = bool(re.search(r'<thinking>', response))
        if has_thinking:
            score += 0.5
        else:
            score -= 1.0

        # Check for <solution> tag
        has_solution = bool(re.search(r'<solution>', response))
        if has_solution:
            score += 0.5
        else:
            score -= 1.0

        # Check for proper closing tags
        closed_thinking = bool(re.search(r'</thinking>', response))
        closed_solution = bool(re.search(r'</solution>', response))

        if closed_thinking and closed_solution:
            score += 1.0
        else:
            score -= 1.0

        # Check if solution is non-empty
        sol_match = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if sol_match:
            sol_content = sol_match.group(1).strip()
            if len(sol_content) > 0:
                score += 1.0
            else:
                score -= 0.5

        # Check for truncation signs (ending abruptly without closing tag or in middle of math)
        if not closed_solution and len(response) > 100:
             score -= 1.0

        scores.append(score)
    return scores

def reward_efficient_reasoning(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        score = 0.0

        think_match = re.search(r'<thinking>(.*?)</thinking>', response, re.DOTALL)
        if not think_match:
            scores.append(-1.0)
            continue

        think = think_match.group(1)

        # Reward for concise reasoning
        # Ideal length is between 200 and 2000 characters
        if 200 <= len(think) <= 2000:
            score += 1.0
        elif len(think) < 200:
            score -= 0.5
        elif len(think) > 5000:
            score -= 1.0
        else:
            score -= 0.5

        # Penalize for excessive repetition
        # Check for repeated lines
        lines = [line.strip() for line in think.split('\n') if line.strip()]
        if len(lines) > 0:
            unique_lines = len(set(lines))
            if unique_lines < len(lines) * 0.8:
                score -= 0.5

        scores.append(score)
    return scores
